import { performance } from 'node:perf_hooks';
import { join } from 'node:path';
const [prefix,root,mode,cacheDirectory]=process.argv.slice(2);
const { defineConfig, duplicateDetection, run } = await import(prefix + '/src/index.ts');
const check=duplicateDetection({
 cache:{enabled:mode==='cache-off'?false:true,directory:cacheDirectory},
 codeAreas:{source:{files:{patterns:mode==='no-eligible'?['src/file-000.ts']:['src/*.ts']},minimumLines:4,minimumTokens:100}},
 scanner:{command:{kind:'custom',executable:join(root,mode==='unavailable'?'missing':'scanner.mjs')}}
});
const config=defineConfig({checks:[check],outputs:{diagnosticLogging:{enabled:false},machinePublication:{enabled:false},progressRendering:{enabled:false}}});
if(mode==='cache-hit')await run(config,{projectRoot:root});
const start=performance.now();
const result=await run(config,{projectRoot:root});
const wallMs=performance.now()-start;
if(result.kind!=='completed')throw new Error(result.kind);
process.stdout.write(JSON.stringify({wallMs,maxRssKiB:process.resourceUsage().maxRSS,outcome:result.snapshot.checks[0]?.outcome,records:result.snapshot.records.length})+'\n');

import pathlib,json,subprocess,hashlib,statistics,math,datetime
base=pathlib.Path('/workspace/vibe-check/tmp/optimization-wave-20261013/duplicate-identity')
protocol=json.loads((base/'protocol.json').read_text()); manifest=json.loads((base/'source-manifest.json').read_text())
versions={'baseline':'/workspace/vibe-check/node_modules/.duplicate-identity-baseline','candidate':'/workspace/vibe-check/node_modules/.duplicate-identity-candidate'}
for name,prefix in versions.items():
 for rel,digest in manifest[name].items():
  if hashlib.sha256((pathlib.Path(prefix)/rel).read_bytes()).hexdigest()!=digest:raise RuntimeError('source drift '+name+'/'+rel)
rows=[];started=datetime.datetime.now(datetime.timezone.utc).isoformat()
for shape in protocol['shapes']:
 for mode in protocol['modes']:
  for rep in range(-protocol['warmups'],protocol['replicates']):
   order=['baseline','candidate'] if rep%2==0 else ['candidate','baseline']
   for version in order:
    cache=str(base/'run-caches'/f'{shape}-{mode}-{version}-{rep}')
    cmd=['mise','exec','--','bun',str(base/'public-api-runner.ts'),versions[version],str(base/'fixtures'/shape),mode,cache]
    run=subprocess.run(cmd,text=True,capture_output=True,check=True)
    data=json.loads(run.stdout);outcome=data['outcome'];expected={'no-eligible':'not-applicable','unavailable':'unavailable'}.get(mode,'passed')
    if outcome['status']!=expected or data['records']!=0:raise RuntimeError('semantic mismatch '+run.stdout)
    rows.append({'shape':shape,'mode':mode,'version':version,'replicate':rep,**data})
    (base/'raw.json').write_text(json.dumps({'startedAt':started,'protocolSha256':hashlib.sha256((base/'protocol.json').read_bytes()).hexdigest(),'manifestSha256':hashlib.sha256((base/'source-manifest.json').read_bytes()).hexdigest(),'samples':rows},indent=2)+'\n')
summary=[]
for shape in protocol['shapes']:
 for mode in protocol['modes']:
  cell={'shape':shape,'mode':mode}
  for v in versions:
   values=[r['wallMs'] for r in rows if r['shape']==shape and r['mode']==mode and r['version']==v and r['replicate']>=0]
   cell[v]={'medianMs':statistics.median(values),'p95Ms':sorted(values)[math.ceil(.95*len(values))-1],'minMs':min(values),'maxMs':max(values)}
  cell['medianRatio']=cell['candidate']['medianMs']/cell['baseline']['medianMs'];summary.append(cell)
(base/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary,indent=2))
